questionvariables.text:
/* Random student names */
names:[
"Mwanza",
"Amina",
"Fatima",
"Grace",
"Neema",
"Juma",
"Baraka",
"Rehema",
"Salma",
"Hassan"
];

/* Select a random name */
student_name:names[1+rand(length(names))];

/* Possible radii (cm) */
radius_values:[4,5,6,7,8,9,10,12,15];

/* Possible heights (cm) */
height_values:[10,12,15,18,20,24,25,30,36];

/* Select a random radius */
radius:radius_values[1+rand(length(radius_values))];

/* Create a list of heights greater than the chosen radius */
valid_heights:sublist(height_values, lambda([x], x > radius));

/* Select a random valid height */
height:valid_heights[1+rand(length(valid_heights))];

/* Use π ≈ 3.142 */
pi_value:3.142;

/* Surface areas */

/* Curved surface area of cylinder */
curved_area:2*pi_value*radius*height;

/* Area of circular base */
base_area:pi_value*radius^2;

/* Correct total external surface area
   (flower pot is open at the top) */
Total_surface_area:round(curved_area + base_area);

/* Common misconceptions */

/* Student omits the base */
No_base_mistake:
round(curved_area);

/* Student incorrectly includes a top circle */
Top_and_base_mistake:
round(curved_area + 2*base_area);

/* Student calculates volume instead */
Volume_mistake:
round(pi_value*radius^2*height);
